	    d__1 = psep + 5.f;
	    d__2 = psey + .5f;
	    d__3 = markstypes_1.typm6[7] * .1f;
	    romano_(&i__, &d__1, &d__2, &c_b1889, &d__3, &c__7);
/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
	    psep = xkf * 1970.f + xkf * 2520.f + seppix[i__] * 1.;
	    psey = xkf * 400.f;
/*      Draw romano in last panel */
	    if (i__ == nribss - 1) {
		i__2 = i__ + 1;
		d__1 = psep + 5.f;
		d__2 = psey + .5f;
		d__3 = markstypes_1.typm6[7] * .1f;
		romano_(&i__2, &d__1, &d__2, &c_b1889, &d__3, &c__7);
	    }
/*      Call draw panel extrados (complete) */
