		    alp = atan((v[i__ + (j + 1501) * 101 - 50601] - v[i__ + (
			    j + 1500) * 101 - 50601]) / (u[i__ + (j + 1501) *
			    101 - 50601] - u[i__ + (j + 1500) * 101 - 50601]))
			    ;
