		point_(&d__1, &d__2, &c__92);
		d__1 = xkf * -2530.f + sepx + xpeq;
		d__2 = sepy - ypeq;
		point_(&d__1, &d__2, &c__92);
		d__1 = xkf * -2530.f + sepx + xpeq + sin(alpha);
		d__2 = sepy - ypeq + cos(alpha);
		point_(&d__1, &d__2, &c__92);
		d__1 = xkf * -2530.f + sepx + xpeq + sin(alpha) * 2;
		d__2 = sepy - ypeq + cos(alpha) * 2;
		point_(&d__1, &d__2, &c__92);
		alpha = atan((v[i__ + 1 + (jcon[i__ + 1 + (ii + 110) * 201 -
			2211] + 1499) * 101 - 50601] - v[i__ + 1 + (jcon[i__
			+ 1 + (ii + 110) * 201 - 2211] + 1501) * 101 - 50601])
			 / (u[i__ + 1 + (jcon[i__ + 1 + (ii + 110) * 201 -
			2211] + 1499) * 101 - 50601] - u[i__ + 1 + (jcon[i__
			+ 1 + (ii + 110) * 201 - 2211] + 1501) * 101 - 50601])
			);
		if (alpha < 0.f) {
/*       alpha=alpha+pi */
		}
		xpeq = ucnt[i__ + 1 + (ii + 110) * 501 - 5511] - xdes * 1.f *
			sin(alpha);
		ypeq = vcnt[i__ + 1 + (ii + 110) * 501 - 5511] + xdes * 1.f *
			cos(alpha);
		d__1 = sepx + xpeq;
		d__2 = sepy - ypeq;
		point_(&d__1, &d__2, &c__92);
		d__1 = sepx + xpeq + sin(alpha);
		d__2 = sepy - ypeq + cos(alpha);
		point_(&d__1, &d__2, &c__92);
		d__1 = sepx + xpeq + sin(alpha) * 2;
		d__2 = sepy - ypeq + cos(alpha) * 2;
		point_(&d__1, &d__2, &c__92);
		d__1 = xkf * -2530.f + sepx + xpeq;
		d__2 = sepy - ypeq;
		point_(&d__1, &d__2, &c__5);
		d__1 = xkf * -2530.f + sepx + xpeq + sin(alpha);
		d__2 = sepy - ypeq + cos(alpha);
		point_(&d__1, &d__2, &c__92);
		d__1 = xkf * -2530.f + sepx + xpeq + sin(alpha) * 2;
		d__2 = sepy - ypeq + cos(alpha) * 2;
		point_(&d__1, &d__2, &c__92);
/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*      Punts marcatge V-rib */
		alpha = atan((vcnt[i__ + 1 + (ii + 110) * 501 - 5511] - vcnt[
			i__ + 1 + (ii + 90) * 501 - 5511]) / (ucnt[i__ + 1 + (
			ii + 110) * 501 - 5511] - ucnt[i__ + 1 + (ii + 90) *
			501 - 5511]));
		xp9 = ucnt[i__ + 1 + (ii + 90) * 501 - 5511] - xdes * sin(
			alpha);
		yp9 = vcnt[i__ + 1 + (ii + 90) * 501 - 5511] + xdes * cos(
			alpha);
		xp11 = ucnt[i__ + 1 + (ii + 110) * 501 - 5511] - xdes * sin(
			alpha);
		yp11 = vcnt[i__ + 1 + (ii + 110) * 501 - 5511] + xdes * cos(
			alpha);
		d__1 = sepx + xp9;
		d__2 = sepy - yp9;
		point_(&d__1, &d__2, &c__3);
		d__1 = sepx + xp11;
		d__2 = sepy - yp11;
		point_(&d__1, &d__2, &c__3);
