				d__4 = psey + pl1y[i__ + j * 101 - 101];
				line_(&d__1, &d__2, &d__3, &d__4, &c__1);
				i__3 = (integer) (jconf[klz - 1] - 1);
				for (j = (integer) jconi[klz - 1]; j <= i__3;
					++j) {
				    d__1 = pl1y[i__ + j * 101 - 101] - yprb[
					    i__ + (klz + 36) * 101 - 101];
				    xpa1 = xkprb[klz - 1] * pow_dd(&d__1, &
					    c_b2202) + xprb[i__ + (klz + 36) *
					     101 - 101];
				    d__1 = pl1y[i__ + (j + 1) * 101 - 101] -
					    yprb[i__ + (klz + 36) * 101 - 101]
					    ;
				    xpa2 = xkprb[klz - 1] * pow_dd(&d__1, &
					    c_b2202) + xprb[i__ + (klz + 36) *
					     101 - 101];
				    d__1 = psep + xpa1;
				    d__2 = psey + pl1y[i__ + j * 101 - 101];
				    d__3 = psep + xpa2;
				    d__4 = psey + pl1y[i__ + (j + 1) * 101 -
					    101];
				    line_(&d__1, &d__2, &d__3, &d__4, &c__1);
				}
