		    xp44 = xtu4[i__ - 1] - (1 - klz + xdes) * cos(alpha);
		    yp44 = xtv4[i__ - 1] - (1 - klz + xdes) * sin(alpha);
		    xu = sepx + xp44;
		    xv = -sepy + yp44;
