/*      Points 6,8 interpolation in rib i */
	    vcnt[i__ + (ii + 60) * 501 - 5511] = (vcnt[i__ + (ii + 90) * 501
		    - 5511] - vcnt[i__ + (ii + 20) * 501 - 5511]) * (hvr[k +
		    804] / 100.f) + vcnt[i__ + (ii + 20) * 501 - 5511];
	    vcnt[i__ + (ii + 80) * 501 - 5511] = (vcnt[i__ + (ii + 110) * 501
		    - 5511] - vcnt[i__ + (ii + 40) * 501 - 5511]) * (hvr[k +
		    804] / 100.f) + vcnt[i__ + (ii + 40) * 501 - 5511];
/* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
