		pd = sqrt(pow_dd(&d__1, &c_b2202) + pow_dd(&d__2, &c_b2202) +
			pow_dd(&d__3, &c_b2202));
		d__1 = rx[i__ + (j + 1) * 101 - 101] - rx[i__ + j * 101 - 101]
			;
		d__2 = ry[i__ + (j + 1) * 101 - 101] - ry[i__ + j * 101 - 101]
			;
		d__3 = rz[i__ + (j + 1) * 101 - 101] - rz[i__ + j * 101 - 101]
			;
		pe = sqrt(pow_dd(&d__1, &c_b2202) + pow_dd(&d__2, &c_b2202) +
			pow_dd(&d__3, &c_b2202));
		d__1 = rx[i__ + 1 + (j + 1) * 101 - 101] - rx[i__ + (j + 1) *
			101 - 101];
