/*      SUBROUTINE d3p */
/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*      SUBROUTINE EXTERNAL POINTS IN A PANEL */
/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*      Computes external points 11-24-14 and 12-25-15 */
/*      in a panel from 1 to npo */
/*      but draws nothing */

/*      WARNING IN REDEFINITION VARIABLES u, v !!! */
/*      ISOLATE THEM! */
/* Subroutine */ int extpoints_(integer *i__, doublereal *uf, doublereal *vf,
	integer *npo, doublereal *xpal, doublereal *xpale, doublereal *xpate,
	integer *icase)
{
    /* Builtin functions */
    double atan(doublereal), sin(doublereal), cos(doublereal);

    /* Local variables */
    static doublereal xru[2], xrv[2], xsu[2], xsv[2];
    static real xtu, xtv;
    static doublereal xupp;
    extern /* Subroutine */ int xrxs_(doublereal *, doublereal *, doublereal *
	    , doublereal *, real *, real *);
    static doublereal alple, alpte, xupple, xuppte;

/*       integer icase */
    /* Parameter adjustments */
    vf -= 50601;
    uf -= 50601;

    /* Function Body */
    xupple = *xpale;
    xuppte = *xpate;
    xupp = *xpal;
/*      WARNING!!! xupp NOT USED */
/*       icase=1 ! Tangent */
/*       icase=2 ! Orthogonal */
/*       icase=1 */
/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*      Case tangent */
/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*      Points LE 14,15,24,25 */
    if (*icase == 1) {
	alple = -atan((vf[*i__ + (*npo + 5000) * 101] - vf[*i__ + (*npo +
		4500) * 101]) / (uf[*i__ + (*npo + 5000) * 101] - uf[*i__ + (*
		npo + 4500) * 101]));
	uf[*i__ + (*npo + 7000) * 101] = uf[*i__ + (*npo + 4500) * 101] +
		xupple * .1f * sin(alple);
	vf[*i__ + (*npo + 7000) * 101] = vf[*i__ + (*npo + 4500) * 101] +
		xupple * .1f * cos(alple);
	uf[*i__ + (*npo + 7500) * 101] = uf[*i__ + (*npo + 5000) * 101] +
		xupple * .1f * sin(alple);
	vf[*i__ + (*npo + 7500) * 101] = vf[*i__ + (*npo + 5000) * 101] +
		xupple * .1f * cos(alple);
/*      recta r (14-15) */
	xru[0] = uf[*i__ + (*npo + 7000) * 101];
	xrv[0] = vf[*i__ + (*npo + 7000) * 101];
	xru[1] = uf[*i__ + (*npo + 7500) * 101];
	xrv[1] = vf[*i__ + (*npo + 7500) * 101];
/*      recta s left (11) */
	xsu[0] = uf[*i__ + (*npo + 5499) * 101];
	xsv[0] = vf[*i__ + (*npo + 5499) * 101];
	xsu[1] = uf[*i__ + (*npo + 5500) * 101];
	xsv[1] = vf[*i__ + (*npo + 5500) * 101];
/*      Intersection 24 */
	xrxs_(xru, xrv, xsu, xsv, &xtu, &xtv);
	uf[*i__ + (*npo + 12000) * 101] = xtu;
	vf[*i__ + (*npo + 12000) * 101] = xtv;
/*      recta s right (11) */
	xsu[0] = uf[*i__ + (*npo + 5999) * 101];
	xsv[0] = vf[*i__ + (*npo + 5999) * 101];
	xsu[1] = uf[*i__ + (*npo + 6000) * 101];
	xsv[1] = vf[*i__ + (*npo + 6000) * 101];
/*      Intersection 24 */
	xrxs_(xru, xrv, xsu, xsv, &xtu, &xtv);
	uf[*i__ + (*npo + 12500) * 101] = xtu;
	vf[*i__ + (*npo + 12500) * 101] = xtv;
/*      Points TE 14,15,24,25 */
	alpte = -atan((vf[*i__ + 505101] - vf[*i__ + 454601]) / (uf[*i__ +
		505101] - uf[*i__ + 454601]));
	uf[*i__ + 707101] = uf[*i__ + 454601] - xuppte * .1f * sin(alpte);
	vf[*i__ + 707101] = vf[*i__ + 454601] - xuppte * .1f * cos(alpte);
	uf[*i__ + 757601] = uf[*i__ + 505101] - xuppte * .1f * sin(alpte);
	vf[*i__ + 757601] = vf[*i__ + 505101] - xuppte * .1f * cos(alpte);
/*      recta r (14-15) */
	xru[0] = uf[*i__ + 707101];
	xrv[0] = vf[*i__ + 707101];
	xru[1] = uf[*i__ + 757601];
	xrv[1] = vf[*i__ + 757601];
/*      recta s left (11) */
	xsu[0] = uf[*i__ + 555601];
	xsv[0] = vf[*i__ + 555601];
	xsu[1] = uf[*i__ + 555702];
	xsv[1] = vf[*i__ + 555702];
/*      Intersection 24 */
	xrxs_(xru, xrv, xsu, xsv, &xtu, &xtv);
	uf[*i__ + 1212101] = xtu;
	vf[*i__ + 1212101] = xtv;
/*      recta s right (11) */
	xsu[0] = uf[*i__ + 606101];
	xsv[0] = vf[*i__ + 606101];
	xsu[1] = uf[*i__ + 606202];
	xsv[1] = vf[*i__ + 606202];
/*      Intersection 25 */
	xrxs_(xru, xrv, xsu, xsv, &xtu, &xtv);
	uf[*i__ + 1262601] = xtu;
	vf[*i__ + 1262601] = xtv;
    }
/* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*      Case orthogonal */
/* ccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
    if (*icase == 2) {
	alple = -atan((vf[*i__ + (*npo + 5000) * 101] - vf[*i__ + (*npo +
		4500) * 101]) / (uf[*i__ + (*npo + 5000) * 101] - uf[*i__ + (*
		npo + 4500) * 101]));
	uf[*i__ + (*npo + 7000) * 101] = uf[*i__ + (*npo + 4500) * 101] +
		xupple * .1f * sin(alple);
	vf[*i__ + (*npo + 7000) * 101] = vf[*i__ + (*npo + 4500) * 101] +
		xupple * .1f * cos(alple);
	uf[*i__ + (*npo + 7500) * 101] = uf[*i__ + (*npo + 5000) * 101] +
		xupple * .1f * sin(alple);
	vf[*i__ + (*npo + 7500) * 101] = vf[*i__ + (*npo + 5000) * 101] +
		xupple * .1f * cos(alple);
	uf[*i__ + (*npo + 12000) * 101] = uf[*i__ + (*npo + 7000) * 101] -
		xupp * .1f * cos(alple);
	vf[*i__ + (*npo + 12000) * 101] = vf[*i__ + (*npo + 7000) * 101] +
		xupp * .1f * sin(alple);
	uf[*i__ + (*npo + 12500) * 101] = uf[*i__ + (*npo + 7500) * 101] +
		xupp * .1f * cos(alple);
	vf[*i__ + (*npo + 12500) * 101] = vf[*i__ + (*npo + 7500) * 101] -
		xupp * .1f * sin(alple);
/*      Points TE 14,15,24,25,26,27 */
/*      TE case orthogonal */
	alpte = -atan((vf[*i__ + 505101] - vf[*i__ + 454601]) / (uf[*i__ +
		505101] - uf[*i__ + 454601]));
	uf[*i__ + 707101] = uf[*i__ + 454601] - xuppte * .1f * sin(alpte);
	vf[*i__ + 707101] = vf[*i__ + 454601] - xuppte * .1f * cos(alpte);
	uf[*i__ + 757601] = uf[*i__ + 505101] - xuppte * .1f * sin(alpte);
	vf[*i__ + 757601] = vf[*i__ + 505101] - xuppte * .1f * cos(alpte);
	uf[*i__ + 1212101] = uf[*i__ + 707101] - xupp * .1f * cos(alpte);
	vf[*i__ + 1212101] = vf[*i__ + 707101] + xupp * .1f * sin(alpte);
	uf[*i__ + 1262601] = uf[*i__ + 757601] + xupp * .1f * cos(alpte);
	vf[*i__ + 1262601] = vf[*i__ + 757601] - xupp * .1f * sin(alpte);
    }
    return 0;
} /* extpoints_ */

/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
