    line_(&d__1, &d__2, &d__3, &d__4, &c__3);
    d__1 = *psep + uf[*i__ + 505101];
    d__2 = *psey - vf[*i__ + 505101];
    d__3 = *psep + uf[*i__ + 606101];
    d__4 = *psey - vf[*i__ + 606101];
    line_(&d__1, &d__2, &d__3, &d__4, &c__3);
/*      Four vertical segments 10-15, 9-14 */
    d__1 = *psep + uf[*i__ + 505101];
