    line_(&d__1, &d__2, &d__3, &d__4, &c__3);
    d__1 = *psep + uf[*i__ + 454601];
    d__2 = *psey - vf[*i__ + 454601];
    d__3 = *psep + uf[*i__ + 707101];
    d__4 = *psey - vf[*i__ + 707101];
    line_(&d__1, &d__2, &d__3, &d__4, &c__3);
    d__1 = *psep + uf[*i__ + (*npo + 4500) * 101];
    d__2 = *psey - vf[*i__ + (*npo + 4500) * 101];
    d__3 = *psep + uf[*i__ + (*npo + 7000) * 101];
    d__4 = *psey - vf[*i__ + (*npo + 7000) * 101];
    line_(&d__1, &d__2, &d__3, &d__4, &c__3);
/*      Two horizontal lines 14-15 */
    d__1 = *psep + uf[*i__ + 707101];
    d__2 = *psey - vf[*i__ + 707101];
    d__3 = *psep + uf[*i__ + 757601];
    d__4 = *psey - vf[*i__ + 757601];
    line_(&d__1, &d__2, &d__3, &d__4, &c__3);
    d__1 = *psep + uf[*i__ + (*npo + 7000) * 101];
    d__2 = *psey - vf[*i__ + (*npo + 7000) * 101];
    d__3 = *psep + uf[*i__ + (*npo + 7500) * 101];
    d__4 = *psey - vf[*i__ + (*npo + 7500) * 101];
    line_(&d__1, &d__2, &d__3, &d__4, &c__3);
/*      Draw eight corner segments */
    d__1 = *psep + uf[*i__ + 707101];
    d__2 = *psey - vf[*i__ + 707101];
