    static doublereal a, b, c__, d__, e, f, g;
    static integer j, k, ii;
    static doublereal ep, xi, mu, uu1, uu2, vv1, vv2;
    static integer len1, len2;
    static doublereal radi;
    static integer kfin;
    static doublereal sfle;
    static integer kini;
    static real xlen;
    static doublereal xlen1, xlen2, omega, tetha, parcu[22], parcv[22], puntu[
	    11], puntv[11], parcul[22], parcvl[22];
    static real xlenco;

    /* Parameter adjustments */
    vf -= 50601;
    uf -= 50601;

    /* Function Body */
    j = *npunt;
/*      Evita radi infinit */
    if (*dfle < 1e-6) {
	*dfle = 1e-5;
/* :) */
    }
/*      ic=1 draw complete borders */
/*      ic=2 draw only external borders */
/*      Set basic points 1-2-3-4 */
    puntu[1] = uf[*i__ + (j + 4500) * 101];
    puntv[1] = vf[*i__ + (j + 4500) * 101];
    puntu[3] = uf[*i__ + (j + 5000) * 101];
    puntv[3] = vf[*i__ + (j + 5000) * 101];
    puntu[4] = (puntu[1] + puntu[3]) * .5;
    puntv[4] = (puntv[1] + puntv[3]) * .5;
    puntu[9] = puntu[3];
    puntv[9] = puntv[3];
    d__1 = puntu[1] - puntu[3];
    d__2 = puntv[1] - puntv[3];
    sfle = sqrt(pow_dd(&d__1, &c_b2202) + pow_dd(&d__2, &c_b2202)) * .5;
    tetha = atan(*dfle / sfle);
    omega = atan((puntv[1] - puntv[3]) / (puntu[3] - puntu[1]));
    if (*is == 1) {
	puntu[2] = puntu[4] + *dfle * sin(omega);
	puntv[2] = puntv[4] + *dfle * cos(omega);
    }
    if (*is == -1) {
	puntu[2] = puntu[4] - *dfle * sin(omega);
	puntv[2] = puntv[4] - *dfle * cos(omega);
    }
/*      Circle by 1-2-3 analytical solution */
    a = (puntu[2] - puntu[1]) * 2.;
    b = (puntv[2] - puntv[1]) * 2.;
    c__ = puntu[1] * puntu[1] - puntu[2] * puntu[2] + puntv[1] * puntv[1] -
	    puntv[2] * puntv[2];
    d__ = (puntu[3] - puntu[2]) * 2.;
    e = (puntv[3] - puntv[2]) * 2.;
    f = puntu[2] * puntu[2] - puntu[3] * puntu[3] + puntv[2] * puntv[2] -
	    puntv[3] * puntv[3];
    puntv[0] = (c__ * d__ / a - f) / (e - b * d__ / a);
    puntu[0] = -(puntv[0] * b + c__) / a;
    d__1 = puntu[1] - puntu[0];
    d__2 = puntv[1] - puntv[0];
    radi = sqrt(pow_dd(&d__1, &c_b2202) + pow_dd(&d__2, &c_b2202));
