/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*     SUBROUTINE planeby123 */
/*     Plane Ax+By+Cz+D=0 defined by points 1,2,3 */
/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/* Subroutine */ int planeby123_(doublereal *punt1, doublereal *punt2,
	doublereal *punt3, doublereal *aplane, doublereal *bplane, doublereal
	*cplane, doublereal *dplane)
{
    static doublereal x1, y1, z1, x2, y2, z2, x3, y3, z3, ag, bg, cg;

    /* Parameter adjustments */
    --punt3;
    --punt2;
    --punt1;

    /* Function Body */
    x1 = punt1[1];
    y1 = punt1[2];
    z1 = punt1[3];
    x2 = punt2[1];
    y2 = punt2[2];
    z2 = punt2[3];
    x3 = punt3[1];
    y3 = punt3[2];
    z3 = punt3[3];
    ag = (y2 - y1) * (z3 - z1) - (z2 - z1) * (y3 - y1);
    bg = (z2 - z1) * (x3 - x1) - (x2 - x1) * (z3 - z1);
    cg = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);
    *aplane = ag;
    *bplane = bg;
    *cplane = cg;
    *dplane = -ag * x1 - bg * y1 - cg * z1;
    return 0;
} /* planeby123_ */

/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/*     Unitary vector and normal to plane by 123 */
/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/* Subroutine */ int unitaryto123_(doublereal *unitv, doublereal *aplane,
	doublereal *bplane, doublereal *cplane)
{
    /* Builtin functions */
    double sqrt(doublereal);

    /* Local variables */
    static doublereal xt;

    /* Parameter adjustments */
    --unitv;

    /* Function Body */
    xt = sqrt(1. / (*aplane * *aplane + *bplane * *bplane + *cplane * *cplane)
	    );
    unitv[1] = xt * *aplane;
    unitv[2] = xt * *bplane;
    unitv[3] = xt * *cplane;
    return 0;
} /* unitaryto123_ */

