/*     SUBROUTINE eo (even odd detection) */
/*     evenodd = 1 ---> odd (parell 28) */
/*     evenodd = 0 ---> even (senar 29) */

/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/* Subroutine */ int eo_(integer *ncells, integer *evenodd)
{
    static integer nribss;
    static real control;

    control = (real) (*ncells) / 2.f - (real) ((integer) ((real) (*ncells) /
	    2.f));
    if (control == 0.f) {
/* even-parell */
	nribss = (integer) ((real) (*ncells) / 2.f + 1.f);
/*      nribss=(ncells/2)+1 */
	*evenodd = 0;
    }
    if (control != 0.f) {
/* odd-senar */
	nribss = (integer) (((real) (*ncells) + 1.f) / 2.f);
/*      nribss=(ncells+1)/2 */
	*evenodd = 1;
    }
    return 0;
} /* eo_ */

