/*     SUBROUTINE distanceabc(x1,y1,z1,x2,y2,z2,x3,y3,z3,distance) */
/*     Calcules point 3 at a distance from 1, in segment between points 1 and 2 */

/* cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc */
/* Subroutine */ int distance123_(doublereal *x1, doublereal *y1, doublereal *
	z1, doublereal *x2, doublereal *y2, doublereal *z2, doublereal *x3,
	doublereal *y3, doublereal *z3, doublereal *distance)
{
    /* Builtin functions */
    double sqrt(doublereal);

    /* Local variables */
    static doublereal distu, distot;

    distot = sqrt((*x2 - *x1) * (*x2 - *x1) + (*y2 - *y1) * (*y2 - *y1) + (*
	    z2 - *z1) * (*z2 - *z1));
    distu = *distance / distot;
    *x3 = *x1 + distu * (*x2 - *x1);
    *y3 = *y1 + distu * (*y2 - *y1);
    *z3 = *z1 + distu * (*z2 - *z1);
    return 0;
} /* distance123_ */

