/* Subroutine */ int replace_in_string__(char *str, char *old, char *new__,
	ftnlen str_len, ftnlen old_len, ftnlen new_len)
{
    /* Builtin functions */
    /* Subroutine */ void s_copy(char *, char *, ftnlen, ftnlen);
    integer s_cmp(char *, char *, ftnlen, ftnlen);

    /* Local variables */
    static integer i__, j, l, oldlen, newlen;
    static char result[2048];
    extern integer len_trim__(char *, ftnlen);

/*     Replace all occurrences of OLD with NEW in STR */
    oldlen = len_trim__(old, old_len);
    newlen = len_trim__(new__, new_len);
    l = len_trim__(str, str_len);
    s_copy(result, " ", (ftnlen)2048, (ftnlen)1);
    j = 1;
    i__ = 1;
    while(i__ <= l) {
	if (i__ <= l - oldlen + 1) {
	    if (s_cmp(str + (i__ - 1), old, i__ + oldlen - 1 - (i__ - 1),
		    oldlen) == 0) {
		if (j < i__) {
		    s_copy(result + (j - 1), str + (j - 1), i__ - 1 - (j - 1),
			     i__ - 1 - (j - 1));
		    j = i__;
		}
		s_copy(result + (j - 1), new__, j + newlen - 1 - (j - 1),
			newlen);
		j += newlen;
		i__ += oldlen;
	    } else {
		*(unsigned char *)&result[j - 1] = *(unsigned char *)&str[i__
			- 1];
		++j;
		++i__;
	    }
	} else {
	    *(unsigned char *)&result[j - 1] = *(unsigned char *)&str[i__ - 1]
		    ;
	    ++j;
	    ++i__;
	}
    }
    s_copy(str, result, str_len, j - 1);
    return 0;
} /* replace_in_string__ */

